css:
/* Style the text loader with a sliding dashed underline */
.text-loader {
  width: fit-content; /* Adjust width to content size */
  font-weight: bold; /* Bold text for emphasis */
  font-family: sans-serif; /* Clean, modern font */
  font-size: 30px; /* Readable size */
  padding: 0 5px 8px 0; /* Space for underline and slight right padding */
  background: repeating-linear-gradient(
    90deg,
    currentColor 0 8%, /* Dash segment */
    #0000 0 10% /* Transparent gap */
  ) 200% 100% / 200% 3px no-repeat; /* Double-width dashed pattern, starts off-screen */
  animation: slideDashes 2s steps(6) infinite; /* Slide animation with stepped timing */
}

/* Add the "Loading..." text via pseudo-element */
.text-loader::before {
  content: "Loading..."; /* Default text content */
}

/* Define the dashed underline slide animation */
@keyframes slideDashes {
  to { background-position: 80% 100%; } /* Slide dashes to the left */
}
